// ============================================================
// MECÂNICA DO BOSS — NÍVEL 3
// ============================================================
const bossAbelha = {
    estado: "preparando", // intro | preparando | atacando | atordoada | derrotada | cutsceneFinal
    ataques: 0,
    vida: 3,
    tempoEstado: 0,
    duracaoAviso: 1200,
    duracaoAtaque: 650,
    duracaoAtordoada: 3000,
    proximoAlvo: 0,
    danoAplicado: false,
    movimentoBaseX: larguraTela / 2,
    movimentoBaseY: 45,
    faseAtaque: 0,
    invulneravelAte: 0,
    tipoAtaque: "horizontal",
    numeroAtaque: 0,
    efeitoDanoAte: 0,
    efeitoDanoInicio: 0,
    cutsceneAte: 0,
    explosaoInicio: 0,
    recompensaAtiva: false,
    recompensaY: -90,
    recompensaColetada: false,
    transicaoMapaVerde: 0,
    transicaoMapaInicio: 0,
    inicioEntrada: 0,
    musicaIniciada: false
};

// As três faixas correspondem às três alturas da arena.
// Elas ficam prontas antes do primeiro frame do boss, para que
// a lógica de colisão não dependa da função de desenho.
const zonasAtaqueAbelha = [
    { x: 0, y: 300, largura: larguraTela, altura: 82, nome: "FAIXA INFERIOR", tipo: "horizontal" },
    { x: 0, y: 220, largura: larguraTela, altura: 82, nome: "FAIXA CENTRAL", tipo: "horizontal" },
    { x: 0, y: 130, largura: larguraTela, altura: 82, nome: "FAIXA SUPERIOR", tipo: "horizontal" }
];

function criarZonasVerticais() {
    return [
        { x: 95, y: 95, largura: 105, altura: 300, nome: "COLUNA ESQUERDA", tipo: "vertical" },
        { x: 347, y: 95, largura: 105, altura: 300, nome: "COLUNA CENTRAL", tipo: "vertical" },
        { x: 600, y: 95, largura: 105, altura: 300, nome: "COLUNA DIREITA", tipo: "vertical" }
    ];
}

function escolherPadraoAtaqueBossAbelha() {
    // Alterna entre ataques horizontais e verticais para que a luta
    // não fique presa em apenas um tipo de movimento.
    bossAbelha.tipoAtaque = (bossAbelha.numeroAtaque % 2 === 0) ? "horizontal" : "vertical";

    if (bossAbelha.tipoAtaque === "vertical") {
        const verticais = criarZonasVerticais();
        bossAbelha.proximoAlvo = Math.floor(Math.random() * verticais.length);
        return verticais;
    }

    bossAbelha.proximoAlvo = Math.floor(Math.random() * zonasAtaqueAbelha.length);
    return zonasAtaqueAbelha;
}

function obterZonasDoPadraoAtual() {
    const lista = bossAbelha.tipoAtaque === "vertical" ? criarZonasVerticais() : zonasAtaqueAbelha;
    const primeira = lista[bossAbelha.proximoAlvo % lista.length];
    if (bossAbelha.faseAtaque === 0) return [primeira];
    const segunda = lista[(bossAbelha.proximoAlvo + 1) % lista.length];
    return [primeira, segunda];
}

function reiniciarBossAbelha() {
    bossAbelha.estado = "aguardandoMusica";
    bossAbelha.ataques = 0;
    bossAbelha.vida = 3;
    bossAbelha.tempoEstado = performance.now();
    bossAbelha.proximoAlvo = Math.floor(Math.random() * zonasAtaqueAbelha.length);
    bossAbelha.danoAplicado = false;
    bossAbelha.faseAtaque = 0;
    bossAbelha.invulneravelAte = 0;
    bossAbelha.numeroAtaque = 0;
    bossAbelha.efeitoDanoAte = 0;
    bossAbelha.efeitoDanoInicio = 0;
    bossAbelha.cutsceneAte = 0;
    bossAbelha.explosaoInicio = 0;
    bossAbelha.recompensaAtiva = false;
    bossAbelha.recompensaY = -90;
    bossAbelha.recompensaColetada = false;
    bossAbelha.transicaoMapaVerde = 0;
    bossAbelha.transicaoMapaInicio = 0;
    bossAbelha.inicioEntrada = performance.now();
    bossAbelha.musicaIniciada = false;
    bossAbelha.tipoAtaque = "horizontal";
    bossAbelha.movimentoBaseX = larguraTela / 2;
    bossAbelha.movimentoBaseY = 45;
    abelhaInferno.x = bossAbelha.movimentoBaseX;
    abelhaInferno.y = bossAbelha.movimentoBaseY;
    abelhaInferno.ativa = false;
    escolherPadraoAtaqueBossAbelha();
}

function obterZonasAtaqueAbelha() {
    return obterZonasDoPadraoAtual();
}

function obterZonaAtaqueAbelha() {
    return obterZonasAtaqueAbelha()[0];
}

function obterCaixaVisualBossAbelha() {
    const largura = 270;
    const areaX = 291;
    const areaY = 377;
    const areaW = 1155;
    const areaH = 741;
    const escala = largura / areaW;
    const altura = areaH * escala;

    return {
        x: abelhaInferno.x - largura / 2,
        y: abelhaInferno.y,
        largura: largura,
        altura: altura
    };
}

function jogadorDentroDeAlgumaZonaBoss(zonas) {
    return zonas.some((zona) =>
        jogador.x + jogador.largura > zona.x && jogador.x < zona.x + zona.largura &&
        jogador.y + jogador.altura > zona.y && jogador.y < zona.y + zona.altura
    );
}

function receberDanoJogadorBoss() {
    const agora = performance.now();
    if (agora < invulneravelJogadorNivel3Ate) return;
    vidaJogadorNivel3 = Math.max(0, vidaJogadorNivel3 - 1);
    efeitoDanoUrsoInicio = agora;
    efeitoDanoUrsoAte = agora + 520;
    invulneravelJogadorNivel3Ate = agora + 1200;
    jogador.x = 55;
    jogador.y = chao - jogador.altura;
    jogador.velocidadeX = 0;
    jogador.velocidadeY = 0;
    jogador.noChao = true;
    if (vidaJogadorNivel3 <= 0) {
        telaDerrotaNivel3 = true;
        inicioDerrotaNivel3 = agora;
        if (window.pararMusicaBatalha) window.pararMusicaBatalha(true);
    }
}

function atualizarBossAbelha() {
    if (numeroFase !== 3 || !abelhaInferno.ativa || telaDerrotaNivel3) return;

    const agora = performance.now();
    const decorrido = agora - bossAbelha.tempoEstado;

    // Entrada cinematográfica do nível 3: a Abbey começa invisível,
    // aparece gradualmente e só depois a luta é liberada.
    if (bossAbelha.estado === "intro") {
        const tIntro = agora - bossAbelha.inicioEntrada;
        const duracaoIntro = 2600;
        const progressoIntro = Math.min(1, tIntro / duracaoIntro);
        const suavizado = 1 - Math.pow(1 - progressoIntro, 3);
        // A Abbey já nasce no centro, sem descer do alto.
        abelhaInferno.x = larguraTela / 2;
        abelhaInferno.y = 55;
        bossAbelha.opacidadeIntro = suavizado;
        if (!bossAbelha.musicaIniciada) {
            bossAbelha.musicaIniciada = true;
            if (window.iniciarMusicaBatalha) window.iniciarMusicaBatalha();
        }
        if (progressoIntro >= 1) {
            bossAbelha.estado = "preparando";
            bossAbelha.tempoEstado = agora;
            escolherPadraoAtaqueBossAbelha();
        }
        return;
    }

    // A abelha fica voando de um lado para o outro durante a luta.
    // Quando está atordoada, ela para para ficar vulnerável.
    if (bossAbelha.estado !== "atordoada" && bossAbelha.estado !== "derrotada") {
        abelhaInferno.x =
            bossAbelha.movimentoBaseX + Math.sin(agora / 500) * 85;
        abelhaInferno.y =
            bossAbelha.movimentoBaseY + Math.sin(agora / 360) * 10;
    } else if (bossAbelha.estado === "atordoada") {
        abelhaInferno.x += (larguraTela / 2 - abelhaInferno.x) * 0.08;
        abelhaInferno.y += (55 - abelhaInferno.y) * 0.08;
    }

    if (bossAbelha.estado === "preparando") {
        if (decorrido >= bossAbelha.duracaoAviso) {
            bossAbelha.estado = "atacando";
            bossAbelha.tempoEstado = agora;
            bossAbelha.danoAplicado = false;
        }
        return;
    }

    if (bossAbelha.estado === "atacando") {
        const alvo = obterZonaAtaqueAbelha();

        const zonas = obterZonasAtaqueAbelha();
        if (!bossAbelha.danoAplicado && jogadorDentroDeAlgumaZonaBoss(zonas)) {
            bossAbelha.danoAplicado = true;
            receberDanoJogadorBoss();
            if (vidaJogadorNivel3 <= 0) return;
        }

        if (decorrido >= bossAbelha.duracaoAtaque) {
            bossAbelha.ataques++;
            bossAbelha.numeroAtaque++;

            if (bossAbelha.ataques >= 4) {
                bossAbelha.estado = "atordoada";
                bossAbelha.tempoEstado = agora;
                bossAbelha.danoAplicado = false;
            } else {
                bossAbelha.estado = "preparando";
                bossAbelha.tempoEstado = agora;
                escolherPadraoAtaqueBossAbelha();
            }
        }
        return;
    }

    if (bossAbelha.estado === "cutsceneFinal") {
        // A cutscene é totalmente automática: congela o boss e o jogador,
        // enquanto a animação é desenhada separadamente.
        const t = agora - bossAbelha.explosaoInicio;
        abelhaInferno.x += (larguraTela / 2 - abelhaInferno.x) * 0.12;
        abelhaInferno.y += (55 - abelhaInferno.y) * 0.12;

        if (t >= 1050) bossAbelha.recompensaAtiva = true;
        if (bossAbelha.recompensaAtiva && !bossAbelha.recompensaColetada) {
            bossAbelha.recompensaY = Math.min(185, bossAbelha.recompensaY + 2.5);

            const melX = larguraTela / 2 - 34;
            const melY = bossAbelha.recompensaY;
            const pertoMel =
                jogador.x + jogador.largura > melX &&
                jogador.x < melX + 68 &&
                jogador.y + jogador.altura > melY &&
                jogador.y < melY + 60;

            if (pertoMel && melY > 80) {
                bossAbelha.recompensaColetada = true;
                bossAbelha.recompensaAtiva = false;
                bossAbelha.transicaoMapaInicio = agora;
                bossAbelha.transicaoMapaVerde = 0;
                bossAbelha.cutsceneAte = agora + 6000;

                // Depois que o urso pega o Mel Divino, o jogador ganha
                // alguns segundos para caminhar pelo mundo restaurado.
                estadoFinalDemo = "explorando";
                inicioFinalDemo = agora;
                inicioEscurecimentoDemo = 0;
                inicioCreditosDemo = 0;
            }
        }

        if (bossAbelha.recompensaColetada) {
            bossAbelha.transicaoMapaVerde = Math.min(1, (agora - bossAbelha.transicaoMapaInicio) / 2200);
        }

        if (agora >= bossAbelha.cutsceneAte) {
            bossAbelha.estado = "derrotada";
            abelhaInferno.ativa = false;
        }
        return;
    }

    if (bossAbelha.estado === "atordoada") {
        const caixa = obterCaixaVisualBossAbelha();

        // Aproximar-se da abelha durante o atordoamento causa um dano.
        const perto =
            jogador.x + jogador.largura > caixa.x - 35 &&
            jogador.x < caixa.x + caixa.largura + 35 &&
            jogador.y + jogador.altura > caixa.y - 35 &&
            jogador.y < caixa.y + caixa.altura + 35;

        if (perto && !bossAbelha.danoAplicado) {
            bossAbelha.danoAplicado = true;
            bossAbelha.vida--;
            bossAbelha.efeitoDanoInicio = agora;
            bossAbelha.efeitoDanoAte = agora + 430;
            ataqueBossJogadorSolicitado = false;
            teclas["KeyX"] = false;

            if (bossAbelha.vida <= 0) {
                // Último golpe: inicia a cutscene de derrota em vez de
                // simplesmente esconder a abelha.
                bossAbelha.estado = "cutsceneFinal";
                if (window.desvanecerMusicaBatalha) window.desvanecerMusicaBatalha();
                bossAbelha.explosaoInicio = agora;
                bossAbelha.cutsceneAte = agora + 5200;
                bossAbelha.recompensaAtiva = false;
                bossAbelha.recompensaY = -90;
                abelhaInferno.ativa = true;
                ataqueBossJogadorSolicitado = false;
                teclas["KeyX"] = false;
                return;
            }

            bossAbelha.faseAtaque = 1;
            bossAbelha.estado = "preparando";
            bossAbelha.tempoEstado = agora;
            bossAbelha.ataques = 0;
            bossAbelha.numeroAtaque = 0;
            escolherPadraoAtaqueBossAbelha();
            bossAbelha.danoAplicado = false;
            return;
        }

        if (decorrido >= bossAbelha.duracaoAtordoada) {
            bossAbelha.estado = "preparando";
            bossAbelha.tempoEstado = agora;
            bossAbelha.ataques = 0;
            escolherPadraoAtaqueBossAbelha();
            bossAbelha.danoAplicado = false;
        }
    }
}

function desenhaCutsceneFinalBossAbelha() {
    if (numeroFase !== 3 || bossAbelha.estado !== "cutsceneFinal") return;

    const agora = performance.now();
    const t = agora - bossAbelha.explosaoInicio;
    const cx = larguraTela / 2;
    const cy = 125;

    ctx.save();

    // Escurecimento cinematográfico nas bordas.
    const vinheta = ctx.createRadialGradient(cx, 210, 60, cx, 210, 520);
    vinheta.addColorStop(0, "rgba(0,0,0,0)");
    vinheta.addColorStop(1, "rgba(0,0,0,0.62)");
    ctx.fillStyle = vinheta;
    ctx.fillRect(0, 0, larguraTela, alturaTela);

    if (t < 1100) {
        const p = Math.min(1, t / 1100);
        const pulso = Math.sin(p * Math.PI);
        const tremor = Math.sin(t / 22) * (1 - p) * 7;

        // Clarão da explosão.
        ctx.globalAlpha = Math.max(0, 0.85 - p * 0.85);
        ctx.fillStyle = "#FFF8B0";
        ctx.fillRect(0, 0, larguraTela, alturaTela);
        ctx.globalAlpha = 1;

        // Núcleo e anéis da explosão.
        ctx.translate(cx + tremor, cy);
        for (let i = 0; i < 3; i++) {
            ctx.globalAlpha = Math.max(0, 0.9 - p - i * 0.18);
            ctx.beginPath();
            ctx.arc(0, 0, 28 + p * (105 + i * 35), 0, Math.PI * 2);
            ctx.strokeStyle = i === 0 ? "#FFFFFF" : (i === 1 ? "#FFE600" : "#FF8A00");
            ctx.lineWidth = 9 - i * 2;
            ctx.stroke();
        }

        // Partículas grandes se afastando.
        ctx.globalAlpha = Math.max(0, 1 - p);
        for (let i = 0; i < 26; i++) {
            const a = i * Math.PI * 2 / 26 + 0.25;
            const r = 25 + p * (85 + (i % 5) * 15);
            const px = Math.cos(a) * r;
            const py = Math.sin(a) * r;
            ctx.fillStyle = i % 3 === 0 ? "#FFFFFF" : (i % 3 === 1 ? "#FFE600" : "#FF9D00");
            ctx.beginPath();
            ctx.arc(px, py, 3 + (i % 4), 0, Math.PI * 2);
            ctx.fill();
        }
        ctx.globalAlpha = 1;
        ctx.restore();

        if (t > 300) {
            ctx.save();
            ctx.textAlign = "center";
            ctx.font = "bold 29px Arial";
            ctx.fillStyle = "#FFFFFF";
            ctx.strokeStyle = "#000000";
            ctx.lineWidth = 6;
            ctx.strokeText("ABELHA DERROTADA!", cx, 350 - pulso * 20);
            ctx.fillText("ABELHA DERROTADA!", cx, 350 - pulso * 20);
            ctx.restore();
        }
        return;
    }

    // Depois da explosão, o céu "entrega" a recompensa.
    if (bossAbelha.recompensaColetada) {
        ctx.restore();
        return;
    }

    const queda = Math.min(1, (t - 1050) / 1800);
    const melX = cx - 34;
    const melY = bossAbelha.recompensaY;

    // Feixe dourado vindo do céu.
    const brilho = 0.35 + Math.abs(Math.sin(agora / 180)) * 0.3;
    ctx.globalAlpha = brilho;
    ctx.fillStyle = "#FFE96A";
    ctx.fillRect(cx - 22, 0, 44, Math.max(0, melY + 30));
    ctx.globalAlpha = 1;

    // Raios e partículas douradas ao redor da recompensa.
    for (let i = 0; i < 18; i++) {
        const a = agora / 500 + i * Math.PI * 2 / 18;
        const r = 42 + (i % 4) * 10;
        const px = cx + Math.cos(a) * r;
        const py = Math.max(35, melY + 28) + Math.sin(a) * r * 0.55;
        ctx.fillStyle = i % 2 ? "#FFF6A0" : "#FFD21F";
        ctx.globalAlpha = 0.45 + Math.abs(Math.sin(agora / 140 + i)) * 0.5;
        ctx.beginPath();
        ctx.arc(px, py, 2 + (i % 3), 0, Math.PI * 2);
        ctx.fill();
    }
    ctx.globalAlpha = 1;

    // Desenha a mesma imagem de Mel Divino usada no jogo, agora em tamanho maior.
    if (imagemMelDivino && imagemMelDivino.complete && imagemMelDivino.naturalWidth > 0) {
        ctx.save();
        ctx.imageSmoothingEnabled = false;
        ctx.shadowColor = "#FFE600";
        ctx.shadowBlur = 22;
        ctx.drawImage(imagemMelDivino, 400, 464, 528, 432, melX, melY, 68, 60);
        ctx.restore();
    } else {
        ctx.save();
        ctx.fillStyle = "#FFD21F";
        ctx.strokeStyle = "#8A5700";
        ctx.lineWidth = 4;
        ctx.beginPath();
        ctx.ellipse(cx, melY + 28, 30, 25, 0, 0, Math.PI * 2);
        ctx.fill();
        ctx.stroke();
        ctx.restore();
    }

    ctx.save();
    ctx.textAlign = "center";
    ctx.font = "bold 27px Arial";
    ctx.fillStyle = "#FFF6A0";
    ctx.strokeStyle = "#4A2600";
    ctx.lineWidth = 6;
    ctx.strokeText("MEL DIVINO", cx, 300);
    ctx.fillText("MEL DIVINO", cx, 300);

    if (queda >= 1) {
        ctx.font = "bold 17px Arial";
        ctx.fillStyle = "#FFFFFF";
        ctx.strokeStyle = "#000000";
        ctx.lineWidth = 4;
        ctx.strokeText("RECOMPENSA CONQUISTADA!", cx, 328);
        ctx.fillText("RECOMPENSA CONQUISTADA!", cx, 328);
    }
    ctx.restore();
}

function desenhaAvisosBossAbelha() {
    if (numeroFase !== 3 || bossAbelha.estado === "aguardandoMusica") return;

    const agora = performance.now();
    const zonas = obterZonasAtaqueAbelha();
    const vertical = bossAbelha.tipoAtaque === "vertical";

    // HUD do chefe.
    ctx.save();
    ctx.fillStyle = "rgba(0,0,0,0.72)";
    ctx.fillRect(205, 8, 390, 67);
    ctx.textAlign = "center";
    ctx.font = "bold 17px Arial";
    let texto = vertical ? "PREPARE-SE! ATAQUE VERTICAL" : "PREPARE-SE! ATAQUE HORIZONTAL";
    if (bossAbelha.estado === "atacando") texto = vertical ? "ATAQUE VERTICAL! DESVIE!" : "ATAQUE HORIZONTAL! DESVIE!";
    if (bossAbelha.estado === "atordoada") texto = "ATORDOADA! ATAQUE A ABELHA!";
    if (bossAbelha.estado === "derrotada") texto = "ABELHA DERROTADA!";
    ctx.fillStyle = "white";
    ctx.fillText(texto, larguraTela / 2, 31);

    const barraX = 275, barraY = 43, barraW = 250, barraH = 15;
    ctx.fillStyle = "#222";
    ctx.fillRect(barraX, barraY, barraW, barraH);
    ctx.fillStyle = "#e53935";
    ctx.fillRect(barraX + 2, barraY + 2, (barraW - 4) * Math.max(0, bossAbelha.vida / 3), barraH - 4);
    ctx.strokeStyle = "white";
    ctx.lineWidth = 2;
    ctx.strokeRect(barraX, barraY, barraW, barraH);
    ctx.restore();

    if (bossAbelha.estado === "derrotada") return;

    if (bossAbelha.estado === "preparando") {
        ctx.save();
        const pisca = 0.22 + Math.abs(Math.sin(agora / 90)) * 0.45;
        for (const zona of zonas) {
            ctx.globalAlpha = pisca;
            ctx.fillStyle = "#FFD21F";
            ctx.fillRect(zona.x, zona.y, zona.largura, zona.altura);
            ctx.globalAlpha = 1;
            ctx.strokeStyle = "#FFF200";
            ctx.lineWidth = 5;
            ctx.setLineDash([12, 8]);
            ctx.strokeRect(zona.x + 2, zona.y + 2, zona.largura - 4, zona.altura - 4);
            ctx.setLineDash([]);
            ctx.fillStyle = "#FFFFFF";
            ctx.font = "bold 15px Arial";
            ctx.textAlign = "center";
            ctx.fillText(vertical ? "PERIGO VERTICAL" : "PERIGO", vertical ? zona.x + zona.largura / 2 : larguraTela / 2, vertical ? zona.y + 22 : zona.y + 21);
        }
        ctx.font = "bold 20px Arial";
        ctx.textAlign = "center";
        ctx.fillStyle = "#FFFFFF";
        ctx.shadowColor = "#000000";
        ctx.shadowBlur = 5;
        ctx.fillText("CUIDADO! " + zonas.length + (vertical ? " COLUNA" : " FAIXA") + (zonas.length > 1 ? "S" : ""), larguraTela / 2, 112);
        ctx.restore();
    }

    if (bossAbelha.estado === "atacando") {
        ctx.save();
        const tempo = agora - bossAbelha.tempoEstado;
        const pulso = (Math.sin(tempo / 55) + 1) / 2;
        const progresso = (tempo % 520) / 520;

        for (const zona of zonas) {
            // Campo de energia que marca exatamente a área perigosa.
            ctx.globalAlpha = 0.42 + pulso * 0.25;
            ctx.fillStyle = "#FF2020";
            ctx.fillRect(zona.x, zona.y, zona.largura, zona.altura);
            ctx.globalAlpha = 1;
            ctx.strokeStyle = "#FFE600";
            ctx.lineWidth = 4;
            ctx.strokeRect(zona.x + 2, zona.y + 2, zona.largura - 4, zona.altura - 4);

            // Núcleo de energia correndo pela área atacada.
            if (!vertical) {
                const px = progresso * (larguraTela + 100) - 50;
                const grad = ctx.createLinearGradient(px - 55, 0, px + 55, 0);
                grad.addColorStop(0, "rgba(255,255,255,0)");
                grad.addColorStop(0.5, "rgba(255,255,255,0.95)");
                grad.addColorStop(1, "rgba(255,255,255,0)");
                ctx.fillStyle = grad;
                ctx.fillRect(px - 55, zona.y, 110, zona.altura);

                // Raios horizontais.
                ctx.strokeStyle = "rgba(255,255,255,0.9)";
                ctx.lineWidth = 2 + pulso * 2;
                for (let i = 0; i < 4; i++) {
                    const yy = zona.y + 12 + i * 18;
                    ctx.beginPath();
                    ctx.moveTo(0, yy);
                    ctx.lineTo(larguraTela * 0.28, yy + Math.sin(tempo / 70 + i) * 5);
                    ctx.lineTo(larguraTela * 0.55, yy - Math.sin(tempo / 65 + i) * 5);
                    ctx.lineTo(larguraTela, yy);
                    ctx.stroke();
                }
            } else {
                const py = zona.y + progresso * zona.altura;
                const grad = ctx.createLinearGradient(0, py - 55, 0, py + 55);
                grad.addColorStop(0, "rgba(255,255,255,0)");
                grad.addColorStop(0.5, "rgba(255,255,255,0.95)");
                grad.addColorStop(1, "rgba(255,255,255,0)");
                ctx.fillStyle = grad;
                ctx.fillRect(zona.x, py - 55, zona.largura, 110);

                // Raios verticais.
                ctx.strokeStyle = "rgba(255,255,255,0.9)";
                ctx.lineWidth = 2 + pulso * 2;
                for (let i = 0; i < 4; i++) {
                    const xx = zona.x + 14 + i * 20;
                    ctx.beginPath();
                    ctx.moveTo(xx, 95);
                    ctx.lineTo(xx + Math.sin(tempo / 70 + i) * 5, 180);
                    ctx.lineTo(xx - Math.sin(tempo / 65 + i) * 5, 285);
                    ctx.lineTo(xx, 395);
                    ctx.stroke();
                }
            }
        }

        // Feixe saindo da abelha em direção às zonas atingidas.
        const bx = abelhaInferno.x;
        const by = abelhaInferno.y + 75;
        ctx.strokeStyle = "rgba(255,245,120,0.9)";
        ctx.lineWidth = 8 + pulso * 5;
        ctx.shadowColor = "#ff3b20";
        ctx.shadowBlur = 18;
        for (const zona of zonas) {
            ctx.beginPath();
            if (vertical) {
                ctx.moveTo(bx, by);
                ctx.lineTo(zona.x + zona.largura / 2, zona.y + zona.altura / 2);
            } else {
                ctx.moveTo(bx, by);
                ctx.lineTo(zona.x + zona.largura / 2, zona.y + zona.altura / 2);
            }
            ctx.stroke();
        }

        // Partículas no centro do ataque.
        ctx.fillStyle = "white";
        for (let i = 0; i < 10; i++) {
            const a = agora / 180 + i;
            const r = 12 + ((agora / 12 + i * 17) % 34);
            const px = abelhaInferno.x + Math.cos(a) * r;
            const py = abelhaInferno.y + 65 + Math.sin(a) * r;
            ctx.globalAlpha = 0.35 + pulso * 0.5;
            ctx.beginPath();
            ctx.arc(px, py, 2 + (i % 3), 0, Math.PI * 2);
            ctx.fill();
        }

        ctx.globalAlpha = 1;
        ctx.shadowBlur = 5;
        ctx.font = "bold 20px Arial";
        ctx.textAlign = "center";
        ctx.fillStyle = "#FFFFFF";
        ctx.fillText("ATAQUE! " + zonas.length + (vertical ? " COLUNA" : " FAIXA") + (zonas.length > 1 ? "S" : ""), larguraTela / 2, 112);
        ctx.restore();
    }

    if (bossAbelha.estado === "atordoada") {
        ctx.save();
        const pisca = 0.65 + Math.abs(Math.sin(agora / 120)) * 0.35;
        ctx.globalAlpha = pisca;
        ctx.font = "bold 20px Arial";
        ctx.textAlign = "center";
        ctx.fillStyle = "#ffe600";
        ctx.shadowColor = "#000000";
        ctx.shadowBlur = 5;
        ctx.fillText("★ ATORDOADA! ATAQUE A ABELHA! ★", larguraTela / 2, 105);
        ctx.restore();
    }
}

