// ============================================================
// ÁREA VISÍVEL DO PNG DO TRONCO
// ============================================================
// O PNG possui transparência ao redor. Estes valores correspondem
// ao retângulo que realmente contém o desenho do tronco.
const TRONCO_FONTE_X = 208;
const TRONCO_FONTE_Y = 576;
const TRONCO_FONTE_LARGURA = 1056;
const TRONCO_FONTE_ALTURA = 992;

// Desce um pouco o desenho para encostar a base no chão.
// Reduzimos também a altura para ficar mais proporcional ao urso.
const TRONCO_AJUSTE_Y = 18;
const TRONCO_ESCALA_ALTURA = 0.85;

// A hitbox fica menor que a imagem para não contar as partes
// externas do tronco como colisão.
const TRONCO_HITBOX_INSET_X = 0.18;
const TRONCO_HITBOX_INSET_TOPO = 0.15;
const TRONCO_HITBOX_INSET_BASE = 0.05;

// ============================================================
// TRONCO 2 — OBSTÁCULO BAIXO
// ============================================================
// Área visível do PNG Tronco 2: x=144, y=544, largura=1008, altura=544.
const TRONCO_BAIXO_FONTE_X = 144;
const TRONCO_BAIXO_FONTE_Y = 544;
const TRONCO_BAIXO_FONTE_LARGURA = 1008;
const TRONCO_BAIXO_FONTE_ALTURA = 544;
const TRONCO_BAIXO_AJUSTE_Y = 20;
const TRONCO_BAIXO_ESCALA_ALTURA = 1;

function obterCaixaColisaoTroncoBaixo(obstaculo) {
    const alturaDesenho =
        obstaculo.largura *
        (TRONCO_BAIXO_FONTE_ALTURA / TRONCO_BAIXO_FONTE_LARGURA);

    const margemX = obstaculo.largura * 0.18;
    const margemTopo = alturaDesenho * 0.20;
    const margemBase = alturaDesenho * 0.05;

    return {
        x: obstaculo.x + margemX,
        y: chao - alturaDesenho + TRONCO_BAIXO_AJUSTE_Y + margemTopo,
        largura: obstaculo.largura - margemX * 2,
        altura: alturaDesenho - margemTopo - margemBase
    };
}

// ============================================================
// HITBOX — TRONCO DUPLO
// ============================================================

function obterCaixaColisaoTroncoDuplo(
    obstaculo
) {

    const larguraTronco =
        obstaculo.largura / 2;


    const alturaDesenho =
        larguraTronco *
        (
            TRONCO_BAIXO_FONTE_ALTURA /
            TRONCO_BAIXO_FONTE_LARGURA
        );


    const margemX =
        larguraTronco * 0.18;

    const margemTopo =
        alturaDesenho * 0.20;

    const margemBase =
        alturaDesenho * 0.05;


    return {

        x:
            obstaculo.x +
            margemX,

        y:
            chao -
            alturaDesenho +
            TRONCO_BAIXO_AJUSTE_Y +
            margemTopo,

        largura:
            obstaculo.largura -
            margemX * 2,

        altura:
            alturaDesenho -
            margemTopo -
            margemBase
    };
}

function obterCaixaColisaoTronco(obstaculo) {

    const alturaDesenho =
        obstaculo.largura *
        (TRONCO_FONTE_ALTURA / TRONCO_FONTE_LARGURA) *
        TRONCO_ESCALA_ALTURA;

    const margemX =
        obstaculo.largura * TRONCO_HITBOX_INSET_X;

    const margemTopo =
        alturaDesenho * TRONCO_HITBOX_INSET_TOPO;

    const margemBase =
        alturaDesenho * TRONCO_HITBOX_INSET_BASE;

    return {
        x: obstaculo.x + margemX,
        y: chao - alturaDesenho + TRONCO_AJUSTE_Y + margemTopo,
        largura: obstaculo.largura - (margemX * 2),
        altura: alturaDesenho - margemTopo - margemBase
    };
}


