function atualizarGamepad() {
    if (!navigator.getGamepads) return;

    const gamepads = navigator.getGamepads();
    let gamepad = controleGamepad;

    if (!gamepad || !gamepads[gamepad.index]) {
        gamepad = null;
        for (let i = 0; i < gamepads.length; i++) {
            if (gamepads[i]) {
                gamepad = gamepads[i];
                break;
            }
        }
    }

    controleGamepad = gamepad;

    // Controles de toque continuam funcionando mesmo com gamepad conectado.
    if (!gamepad || !jogoIniciado || estadoInfinito === "fim" || estadoInfinito === "resultado") {
        teclasGamepad.esquerda = false;
        teclasGamepad.direita = false;
        teclasGamepad.baixo = false;
        teclasGamepad.pulo = false;
        return;
    }

    const eixoX = gamepad.axes && gamepad.axes.length > 0 ? gamepad.axes[0] : 0;

    // Padrão comum de controle: A = 0, B = 1, Y = 3, D-pad = 13/14/15.
    const esquerdaDpad = !!(gamepad.buttons[14] && gamepad.buttons[14].pressed);
    const direitaDpad = !!(gamepad.buttons[15] && gamepad.buttons[15].pressed);
    const baixoDpad = !!(gamepad.buttons[13] && gamepad.buttons[13].pressed);
    const puloBotao = !!(gamepad.buttons[0] && gamepad.buttons[0].pressed);
    const puloAlternativo = !!(gamepad.buttons[3] && gamepad.buttons[3].pressed);
    const agacharBotao = !!(gamepad.buttons[1] && gamepad.buttons[1].pressed);

    const esquerda = eixoX < -0.28 || esquerdaDpad;
    const direita = eixoX > 0.28 || direitaDpad;
    const agachar = baixoDpad || agacharBotao;
    const pulo = puloBotao || puloAlternativo;

    // O gamepad fica separado das teclas físicas para não sobrescrever
    // as setas do teclado quando um controle estiver conectado.
    teclasGamepad.esquerda = esquerda;
    teclasGamepad.direita = direita;
    teclasGamepad.baixo = agachar;
    teclasGamepad.pulo = pulo;

    if ((agachar || controlesVirtuais.agachar) && jogador.noChao) {
        jogador.agachado = true;
    } else if (!agachar && !controlesVirtuais.agachar) {
        jogador.agachado = false;
    }

    // O pulo é acionado na borda do botão para não repetir automaticamente.
    if (pulo && !botaoPuloAnterior) {
        pularVirtual();
    }

    botaoPuloAnterior = pulo;
}

window.addEventListener("gamepadconnected", function (e) {
    controleGamepad = e.gamepad;
});

window.addEventListener("gamepaddisconnected", function (e) {
    if (controleGamepad && controleGamepad.index === e.gamepad.index) {
        controleGamepad = null;
        botaoPuloAnterior = false;
    }
});



// ============================================================
// INICIALIZAÇÃO
// ============================================================

window.onload = function () {

    tela =
        document.getElementById(
            "tela"
        );


    tela.width =
        larguraTela;

    tela.height =
        alturaTela;


    // ========================================================
    // CONFIGURAÇÃO DO DOCUMENTO
    // ========================================================

    document.body.style.margin = "0";
    document.body.style.padding = "0";
    document.body.style.overflow = "hidden";
    document.body.style.backgroundColor = "#000000";
    document.body.style.touchAction = "none";
    document.body.style.userSelect = "none";
    document.documentElement.style.width = "100%";
    document.documentElement.style.height = "100%";
    document.documentElement.style.overflow = "hidden";

    const metaViewport = document.querySelector('meta[name="viewport"]') || document.createElement("meta");
    metaViewport.name = "viewport";
    metaViewport.content = "width=device-width, initial-scale=1, maximum-scale=1, user-scalable=no, viewport-fit=cover";
    if (!metaViewport.parentNode) document.head.appendChild(metaViewport);

    adicionarEstiloControlesCelular();
    configurarControlesCelular();


    // ========================================================
    // CONFIGURAÇÃO DO CANVAS
    // ========================================================

    tela.style.display = "block";

    tela.style.position = "fixed";

    tela.style.margin = "0";

    tela.style.padding = "0";

    tela.style.border = "0";

    tela.style.imageRendering = "pixelated";


    ctx =
        tela.getContext(
            "2d"
        );


    ctx.imageSmoothingEnabled =
        false;


    document.addEventListener(
        "keydown",
        pressionou
    );


    document.addEventListener(
        "keyup",
        soltou
    );


    tela.addEventListener(
        "click",
        cliqueMenu
    );


    window.addEventListener(
        "resize",
        ajustarTela
    );


    window.addEventListener(
        "resize",
        posicionarInputNome
    );


    if (window.visualViewport) {
        window.visualViewport.addEventListener("resize", ajustarTela);
        window.visualViewport.addEventListener("scroll", ajustarTela);
    }


    document.addEventListener(
        "fullscreenchange",
        ajustarTela
    );


    ajustarTela();


    requestAnimationFrame(
        update
    );
};


// ============================================================
// AJUSTAR CANVAS PARA A ÁREA VISÍVEL
// ============================================================

function ajustarTela() {

    if (!tela) {

        return;
    }


    const larguraJanela =
        (window.visualViewport && window.visualViewport.width) ||
        document.documentElement.clientWidth ||
        window.innerWidth;


    const alturaJanela =
        (window.visualViewport && window.visualViewport.height) ||
        document.documentElement.clientHeight ||
        window.innerHeight;


    const escalaX =
        larguraJanela /
        larguraTela;


    const escalaY =
        alturaJanela /
        alturaTela;


    const escala =
        Math.min(
            escalaX,
            escalaY
        );


    const novaLargura =
        Math.floor(
            larguraTela *
            escala
        );


    const novaAltura =
        Math.floor(
            alturaTela *
            escala
        );


    tela.style.width =
        novaLargura + "px";


    tela.style.height =
        novaAltura + "px";


    const esquerda =
        Math.floor(
            (
                larguraJanela -
                novaLargura
            ) / 2
        );


    const topo =
        Math.floor(
            (
                alturaJanela -
                novaAltura
            ) / 2
        );


    tela.style.left =
        esquerda + "px";


    tela.style.top =
        topo + "px";


    tela.style.maxWidth =
        "100vw";


    tela.style.maxHeight =
        "100vh";


    tela.style.transform =
        "none";


    tela.style.imageRendering =
        "pixelated";


    posicionarInputNome();
    atualizarVisibilidadeControles();
}


// ============================================================
// ENTRAR EM TELA CHEIA
// ============================================================

function entrarTelaCheia() {

    ajustarTela();

    if (
        (navigator.maxTouchPoints > 0 || "ontouchstart" in window) &&
        !document.fullscreenElement &&
        tela &&
        tela.requestFullscreen
    ) {
        tela.requestFullscreen().catch(function () {});
    }
}


// ============================================================
// TECLA PRESSIONADA
// ============================================================

function pressionou(e) {

    teclas[e.code] = true;


    if (
        e.code === "Space" ||
        e.code === "ArrowUp" ||
        e.code === "ArrowDown"
    ) {

        e.preventDefault();
    }


    // ========================================================
    // AGACHAR
    // ========================================================

    if (
        e.code === "ArrowDown" ||
        e.code === "KeyS"
    ) {

        if (
            jogador.noChao &&
            jogoIniciado
        ) {

            jogador.agachado = true;
        }
    }


    // ========================================================
    // TELA DE NOME
    // ========================================================

    if (
        modoAtual === "infinito" &&
        estadoInfinito === "fim"
    ) {

        if (
            e.code === "Enter"
        ) {

            confirmarPontuacao();

            return;
        }


        if (
            e.code === "Escape"
        ) {

            removerInputNome();

            voltarMenu();

            return;
        }


        return;
    }


    // ========================================================
    // SE NÃO ESTIVER JOGANDO
    // ========================================================

    if (
        !jogoIniciado
    ) {

        return;
    }


    // ========================================================
    // PULO
    // ========================================================

    if (
        e.code === "Space" ||
        e.code === "ArrowUp" ||
        e.code === "KeyW"
    ) {

        pularVirtual();

    }
}


// ============================================================
// TECLA SOLTA
// ============================================================

function soltou(e) {
    teclas[e.code] = false;

    if (
        e.code === "ArrowDown" ||
        e.code === "KeyS"
    ) {
        jogador.agachado = false;
    }

    if (
        e.code === "Space" ||
        e.code === "ArrowUp" ||
        e.code === "KeyW"
    ) {
        puloPressionado = false;
    }
}


// ============================================================
// CLIQUES
// ============================================================

function cliqueMenu(e) {

    entrarTelaCheia();


    const rect =
        tela.getBoundingClientRect();


    const escalaX =
        larguraTela /
        rect.width;


    const escalaY =
        alturaTela /
        rect.height;


    const mouseX =
        (
            e.clientX -
            rect.left
        ) *
        escalaX;


    const mouseY =
        (
            e.clientY -
            rect.top
        ) *
        escalaY;


    // ========================================================
    // MENU PRINCIPAL
    // ========================================================

    if (
        !jogoIniciado
    ) {

        if (
            mouseX >= 250 &&
            mouseX <= 550 &&
            mouseY >= 270 &&
            mouseY <= 330
        ) {

            iniciarClassico();

            return;
        }


        if (
            mouseX >= 250 &&
            mouseX <= 550 &&
            mouseY >= 340 &&
            mouseY <= 400
        ) {

            iniciarInfinito();

            return;
        }


        return;
    }


    // ========================================================
    // RESULTADO INFINITO
    // ========================================================

    if (
        modoAtual === "infinito" &&
        estadoInfinito === "resultado"
    ) {

        // As áreas de clique devem coincidir com os botões desenhados
        // no centro da tela de resultado (800x450).
        const botaoRecomecar = { x: 200, y: 120, largura: 400, altura: 185 };
        const botaoMenu = { x: 270, y: 290, largura: 260, altura: 170 };

        if (
            mouseX >= botaoRecomecar.x &&
            mouseX <= botaoRecomecar.x + botaoRecomecar.largura &&
            mouseY >= botaoRecomecar.y &&
            mouseY <= botaoRecomecar.y + botaoRecomecar.altura
        ) {
            iniciarInfinito();
            return;
        }

        if (
            mouseX >= botaoMenu.x &&
            mouseX <= botaoMenu.x + botaoMenu.largura &&
            mouseY >= botaoMenu.y &&
            mouseY <= botaoMenu.y + botaoMenu.altura
        ) {
            voltarMenu();
            return;
        }
    }
}


// ============================================================
// VOLTAR AO MENU
// ============================================================

function voltarMenu() {

    jogoIniciado = false;

    modoAtual = null;

    estadoInfinito = "jogando";

    obstaculos = [];

    removerInputNome();


    jogador.x = 100;

    jogador.y =
        chao -
        jogador.alturaNormal;

    jogador.altura =
        jogador.alturaNormal;

    jogador.velocidadeX = 0;

    jogador.velocidadeY = 0;

    jogador.noChao = true;

    jogador.andando = false;

    jogador.animacao = 0;

    jogador.direcao = 1;

    jogador.agachado = false;

    jogador.agachamento = 0;

    jogador.alvoAgachamento = 0;


    cameraX = 0;
    atualizarVisibilidadeControles();


    ajustarTela();
}


// ============================================================
// ====================== MODO CLÁSSICO =======================
// ============================================================

function iniciarClassico() {

    modoAtual = "classico";

    jogoIniciado = true;

    numeroFase = 0;

    obstaculos = [];
    plataformasClassico = [];


    jogador.x = 100;

    jogador.altura =
        jogador.alturaNormal;

    jogador.y =
        chao -
        jogador.altura;

    jogador.velocidadeX = 0;

    jogador.velocidadeY = 0;

    jogador.noChao = true;

    jogador.andando = false;

    jogador.animacao = 0;

    jogador.direcao = 1;

    jogador.agachado = false;

    jogador.agachamento = 0;

    jogador.alvoAgachamento = 0;


    cameraX = 0;
    abelhaInferno.ativa = false;
    estadoFinalDemo = "normal";
    telaDerrotaNivel3 = false;
    inicioFinalDemo = 0;
    inicioEscurecimentoDemo = 0;
    inicioCreditosDemo = 0;


    gerarObstaculos();
    atualizarVisibilidadeControles();
}


// ============================================================
// GERAR NOVA FASE
// ============================================================

function gerarObstaculos() {

    obstaculos = [];

    numeroFase++;

    criarObstaculosFase();
}


// ============================================================
// CRIAR OBSTÁCULOS DA FASE
// ============================================================

function criarObstaculosFase() {

    obstaculos = [];

    // O nível 2 usa plataformas fixas em vez de obstáculos aleatórios.
    if (numeroFase === 2) {
        criarPlataformasNivel2();
        return;
    }

    // O nível 3 também não possui obstáculos no chão.
    if (numeroFase === 3) {
        criarPlataformasNivel3();
        return;
    }


    const quantidade =
        inteiroAleatorio(
            12,
            18
        );


    let tentativas = 0;


    while (
        obstaculos.length <
        quantidade &&
        tentativas < 3000
    ) {

        tentativas++;


        const x =
            inteiroAleatorio(
                500,
                larguraMundo - 150
            );


        let podeCriar = true;


        for (
            let obstaculo of obstaculos
        ) {

            const distancia =
                Math.abs(
                    x -
                    obstaculo.x
                );


            if (
                distancia < 170
            ) {

                podeCriar = false;

                break;
            }
        }


        if (
            !podeCriar
        ) {

            continue;
        }


        const sorteio =
            Math.random();


        let tipo;


        // No modo CLÁSSICO existem apenas dois tipos:
        // baixo e alto. Obstáculos de abaixar ficam
        // exclusivos do modo INFINITO.
        if (
            sorteio < 0.50
        ) {

            tipo = "baixo";

        } else {

            tipo = "alto";
        }


        if (
            tipo === "baixo"
        ) {

            obstaculos.push({

                x: x,

                // Tamanho FIXO para todos os obstáculos baixos (Tronco 2)
                largura: 90,

                altura: 49,

                profundidade: 15,

                tipo: "baixo"
            });

        } else if (
            tipo === "alto"
        ) {

            obstaculos.push({

                x: x,

                // Tamanho FIXO para todos os obstáculos altos
                largura: 90,

                altura: 113,

                profundidade: 18,

                tipo: "alto"
            });

        }
    }


    obstaculos.sort(
        function (a, b) {

            return a.x - b.x;
        }
    );
}


// ============================================================
// PLATAFORMAS FIXAS — NÍVEL 2
