// ============================================================
// MURAL DE PONTOS E BOTÕES PERSONALIZADOS
// ============================================================

function desenhaMuralPontos() {

    const x = 55;
    const y = 52;
    const largura = 175;
    const altura = 337;

    ctx.save();
    ctx.imageSmoothingEnabled = false;

    if (
        imagemMuralPontos.complete &&
        imagemMuralPontos.naturalWidth > 0
    ) {
        // Recorta apenas a área visível do mural, retirando
        // o espaço transparente original para que ele fique grande.
        ctx.drawImage(
            imagemMuralPontos,
            30, 1, 42, 81,
            x, y, largura, altura
        );
    } else {
        ctx.fillStyle = "#7cc7e8";
        ctx.fillRect(x, y, largura, altura);
        ctx.strokeStyle = "#202020";
        ctx.lineWidth = 4;
        ctx.strokeRect(x, y, largura, altura);
    }

    ctx.restore();

    // O placar fica dentro do painel azul do mural.
    const centroX = x + largura / 2;
    const topo = y + 48;

    ctx.save();
    ctx.textAlign = "center";
    ctx.textBaseline = "middle";
    ctx.fillStyle = "#111111";

    ctx.font = "bold 16px Arial";
    ctx.fillText("TOP 10", centroX, topo);

    if (placar.length === 0) {
        ctx.font = "bold 12px Arial";
        ctx.fillText("Nenhuma pontuação", centroX, topo + 35);
        ctx.restore();
        return;
    }

    const limite = Math.min(10, placar.length);
    const inicio = topo + 26;

    for (let i = 0; i < limite; i++) {
        const jogadorPlacar = placar[i];
        const posicaoY = inicio + i * 25;
        const nome = String(jogadorPlacar.nome || "SEM NOME");
        const nomeCurto = nome.length > 10 ? nome.slice(0, 10) + "…" : nome;

        ctx.font = i === 0 ? "bold 12px Arial" : "bold 11px Arial";
        ctx.fillText(
            (i + 1) + ". " + nomeCurto,
            centroX,
            posicaoY
        );

        ctx.font = "bold 11px Arial";
        ctx.fillText(
            String(jogadorPlacar.pontos),
            centroX,
            posicaoY + 12
        );
    }

    ctx.restore();
}

function desenhaImagemBotaoFim(
    imagem,
    x,
    y,
    largura,
    altura,
    recorteLargura,
    recorteAltura
) {

    if (!imagem.complete || imagem.naturalWidth <= 0) return;

    ctx.save();
    ctx.imageSmoothingEnabled = false;

    // As imagens possuem áreas transparentes grandes.
    // Aqui usamos somente a arte visível para manter o botão grande.
    if (imagem === imagemBotaoRecomecarFim) {
        ctx.drawImage(
            imagem,
            90, 177, 402, 209,
            x, y, largura, altura
        );
    } else {
        ctx.drawImage(
            imagem,
            96, 2, 402, 186,
            x, y, largura, altura
        );
    }

    ctx.restore();
}


