// ============================================================
// MENU PRINCIPAL
// ============================================================

function desenhaMenu() {

    // ========================================================
    // ANIMAÇÃO DO FUNDO
    // ========================================================

    movimentoMenu +=
        velocidadeMovimentoMenu;


    ctx.clearRect(
        0,
        0,
        larguraTela,
        alturaTela
    );

    // Durante a transição, o menu inteiro sobe de baixo para cima.
    ctx.save();
    ctx.translate(0, deslocamentoMenuTransicaoDemo);


    // ========================================================
    // CENÁRIO PASSANDO
    // ========================================================

    if (
        imagemCenario.complete &&
        imagemCenario.naturalWidth > 0
    ) {

        const larguraImagem =
            larguraTela;

        const alturaImagem =
            alturaTela;


        const deslocamento =
            -(
                movimentoMenu %
                larguraImagem
            );


        // Desenha várias cópias
        // para não aparecer espaço preto
        for (
            let i = -1;
            i <= 1;
            i++
        ) {

            ctx.drawImage(

                imagemCenario,

                deslocamento +
                i *
                larguraImagem,

                0,

                larguraImagem,
                alturaImagem
            );
        }

    } else {

        // ====================================================
        // FUNDO ALTERNATIVO
        // ====================================================

        const gradiente =
            ctx.createLinearGradient(
                0,
                0,
                0,
                alturaTela
            );


        gradiente.addColorStop(
            0,
            "#87CEEB"
        );


        gradiente.addColorStop(
            1,
            "#DDF5FF"
        );


        ctx.fillStyle =
            gradiente;


        ctx.fillRect(
            0,
            0,
            larguraTela,
            alturaTela
        );
    }


    // ========================================================
    // ESCURECER O FUNDO
    // ========================================================

    ctx.fillStyle =
        "rgba(0,0,0,0.30)";


    ctx.fillRect(
        0,
        0,
        larguraTela,
        alturaTela
    );


    // ========================================================
    // TÍTULO COM AS DUAS IMAGENS
    // ========================================================

    if (
        imagemTituloMarrom.complete &&
        imagemTituloMarrom.naturalWidth > 0 &&
        imagemTituloVerde.complete &&
        imagemTituloVerde.naturalWidth > 0
    ) {

        // A imagem original possui bastante espaço transparente.
        // Por isso usamos apenas a parte que contém o desenho.

        const larguraTitulo = 350;

        // IMAGEM MARROM - "JOGO"
        const alturaMarrom =
            larguraTitulo * (493 / 1588);

        ctx.drawImage(
            imagemTituloMarrom,
            199, 452, 1588, 493,
            (larguraTela - larguraTitulo) / 2,
            8,
            larguraTitulo,
            alturaMarrom
        );

        // IMAGEM VERDE - "PLATAFORMA"
        const alturaVerde =
            larguraTitulo * (639 / 1973);

        ctx.drawImage(
            imagemTituloVerde,
            59, 869, 1973, 639,
            (larguraTela - larguraTitulo) / 2,
            8 + alturaMarrom - 5,
            larguraTitulo,
            alturaVerde
        );

    } else {

        // Título de emergência caso as imagens não carreguem
        ctx.fillStyle =
            "#FFFFFF";

        ctx.font =
            "bold 48px Arial";

        ctx.textAlign =
            "center";

        ctx.strokeStyle =
            "#000000";

        ctx.lineWidth = 5;

        ctx.strokeText(
            "JOGO PLATAFORMA",
            larguraTela / 2,
            85
        );

        ctx.fillText(
            "JOGO PLATAFORMA",
            larguraTela / 2,
            85
        );
    }


    // ========================================================
    // SUBTÍTULO
    // ========================================================

    ctx.fillStyle =
        "#FFFFFF";

    ctx.font =
        "bold 20px Arial";

    ctx.textAlign =
        "center";

    ctx.strokeStyle =
        "#000000";

    ctx.lineWidth = 4;

    ctx.strokeText(
        "ESCOLHA UM MODO DE JOGO",
        larguraTela / 2,
        245
    );

    ctx.fillText(
        "ESCOLHA UM MODO DE JOGO",
        larguraTela / 2,
        245
    );


// ========================================================
// BOTÃO CLÁSSICO
// ========================================================

desenhaBotao(

    250,
    240,
    300,
    150,

    "CLÁSSICO"
);


// ========================================================
// BOTÃO INFINITO
// ========================================================

desenhaBotao(

    250,
    310,
    300,
    150,

    "INFINITO"
);
    ctx.restore();
}


// ============================================================
// BOTÃO MENU
// ============================================================

function desenhaBotao(
    x,
    y,
    largura,
    altura,
    texto
) {

    let imagemBotao = null;


    // ========================================================
    // ESCOLHER A IMAGEM DO BOTÃO
    // ========================================================

    if (texto === "CLÁSSICO") {

        imagemBotao =
            imagemBotaoClassico;

    } else if (texto === "INFINITO") {

        imagemBotao =
            imagemBotaoInfinito;
    }


    // ========================================================
    // DESENHAR A IMAGEM
    // ========================================================

    if (
        imagemBotao &&
        imagemBotao.complete &&
        imagemBotao.naturalWidth > 0
    ) {

        ctx.save();

        ctx.imageSmoothingEnabled = false;


    ctx.drawImage(
        imagemBotao,
        x,
        y,
        largura,
        altura
    );


        ctx.restore();

        return;
    }


    // ========================================================
    // RESERVA CASO A IMAGEM NÃO CARREGUE
    // ========================================================

    ctx.fillStyle =
        "rgba(255,255,255,0.92)";


    ctx.fillRect(
        x,
        y,
        largura,
        altura
    );


    ctx.strokeStyle =
        "#000000";


    ctx.lineWidth = 3;


    ctx.strokeRect(
        x,
        y,
        largura,
        altura
    );


    ctx.fillStyle =
        "#000000";


    ctx.font =
        "bold 24px Arial";


    ctx.textAlign =
        "center";


    ctx.fillText(
        texto,
        x + largura / 2,
        y + 38
    );
}

// ============================================================
// FUNÇÃO AUXILIAR
// ============================================================

function inteiroAleatorio(
    min,
    max
) {

    return Math.floor(
        Math.random() *
        (
            max -
            min +
            1
        )
    ) + min;
}


// Botão da tela de derrota do último nível.
window.addEventListener("click", function(event) {
    if (!telaDerrotaNivel3 || !tela) return;
    const r = tela.getBoundingClientRect();
    const x = (event.clientX-r.left) * (larguraTela/r.width);
    const y = (event.clientY-r.top) * (alturaTela/r.height);
    if (x >= 270 && x <= 530 && y >= 350 && y <= 405) {
        telaDerrotaNivel3 = false;
        numeroFase = 1;
        vidaJogadorNivel3 = 3;
        estadoFinalDemo = "normal";
        reiniciarFaseAtual();
        if (window.pararMusicaBatalha) window.pararMusicaBatalha(false);
        if (window.iniciarMusicaPrincipal) window.iniciarMusicaPrincipal(true);
    }
});
